import net.jcip.annotations.GuardedBy

class Bad1 {
    companion object { const val FIELD = "field" }
    @GuardedBy(FIELD) // bad - not a string literal
    var data: String = ""
}

import net.jcip.annotations.GuardedBy

class Bad2 {
    @GuardedBy("nonExistent") // bad - no such field
    var data: String = ""
}

import net.jcip.annotations.GuardedBy

class Bad3 {
    @GuardedBy("this") // bad - no sync mechanism
    var data: String = ""

    fun setData(d: String) { data = d }
}

import net.jcip.annotations.GuardedBy

class Bad4 {
    var lock = Any() // bad - lock should be private val
    @GuardedBy("lock")
    var data: String = ""

    fun setData(d: String) {
        synchronized(lock) { data = d }
    }
}

import net.jcip.annotations.GuardedBy

class Bad5 {
    val lock = Any() // bad - not private
    @GuardedBy("lock")
    var data: String = ""

    fun setData(d: String) {
        synchronized(lock) { data = d }
    }
}

import net.jcip.annotations.GuardedBy

class Good1 {
    private val lock = Any()
    @GuardedBy("lock")
    var data: String = ""

    fun setData(d: String) {
        synchronized(lock) { data = d }
    }
}

import net.jcip.annotations.GuardedBy

class Good2 {
    @GuardedBy("this")
    var data: String = ""

    @Synchronized
    fun setData(d: String) { data = d }
}

import net.jcip.annotations.GuardedBy

class Good3 {
    @GuardedBy("this")
    var data: String = ""

    fun setData(d: String) {
        synchronized(this) { data = d }
    }
}

import net.jcip.annotations.GuardedBy

class Good5 {
    companion object {
        private val lock = Any()
        @GuardedBy("lock")
        var shared: String = ""
    }

    fun setShared(d: String) {
        synchronized(lock) { shared = d }
    }
}
